from taf.internal.rpc.pyro.proxy import PyroProxy


class MTKProxy(PyroProxy):
    def __init__(self, url, timeout=None):
        super(MTKProxy, self).__init__(url, timeout=timeout)
        object_id = id(self)
        self._ota_message_alias = 'OTA_{}'.format(object_id)
        self._ota_details_alias = 'OTA_DETAILS_{}'.format(object_id)
        self._systrace_alias = 'SYSTRACE_{}'.format(object_id)
        self._pstrace_alias = 'PSTRACE_{}'.format(object_id)
        self._raw_string_alias = 'RAW_STRING_{}'.format(object_id)

    def get_ota_message_alias(self):
        return self._ota_message_alias

    def get_ota_details_alias(self):
        return self._ota_details_alias

    def get_systrace_alias(self):
        return self._systrace_alias

    def get_pstrace_alias(self):
        return self._pstrace_alias

    def get_raw_string_alias(self):
        return self._raw_string_alias

    def connect_device(self, edb_file_path, com=None):
        com = 'auto' if not com else com
        return self.raw_proxy.connect_device(edb_file_path, com)

    def disconnect_device(self):
        return self.raw_proxy.disconnect_device()

    def get_platform_information(self):
        return self.raw_proxy.get_platform_information()

    def is_com_ports_ready(self, port_names=None):
        return self.raw_proxy.ports_ready(port_names)

    def set_filter(self, filter_name=None):
        filter_name = "2.Gen97_Default_Standard" if not filter_name else filter_name
        return self.raw_proxy.set_filter(filter_name=filter_name)

    def save_elg_log(self, output_path):
        return self.raw_proxy.save_elg_log(output_path)

    def inject_message(self, message_id, src_module, dest_module, sap, local_param):
        return self.raw_proxy.inject_message(message_id, src_module, dest_module, sap, local_param)

    def send_at_command(self, cmd):
        return self.raw_proxy.send_at_command(cmd)

    def set_log_collector_start_timestamp(self):
        self.raw_proxy.set_log_collector_start_timestamp()

    def read_ota_message_until(self, expected, wait_timeout=5):
        return self.raw_proxy.read_ota_text_message_until(self.get_ota_message_alias(), expected, wait_timeout)

    def read_ota_message_details_until(self, expected, wait_timeout=5):
        return self.raw_proxy.read_ota_json_message_until(self.get_ota_details_alias(), expected, wait_timeout)

    def read_systrace_until(self, expected, wait_timeout=5):
        return self.raw_proxy.read_system_trace_until(self.get_systrace_alias(), expected, wait_timeout)

    def read_pstrace_until(self, expected, wait_timeout=5):
        return self.raw_proxy.read_ps_trace_until(self.get_pstrace_alias(), expected, wait_timeout)

    def read_raw_string_until(self, expected, wait_timeout):
        return self.raw_proxy.read_raw_string_until(self.get_raw_string_alias(), expected, wait_timeout)

    def read_latest_ota_message(self):
        return self.raw_proxy.read_latest_ota_text_message(self.get_ota_message_alias())

    def read_latest_ota_message_details(self):
        return self.raw_proxy.read_latest_ota_json_message(self.get_ota_details_alias())

    def read_latest_systrace(self):
        return self.raw_proxy.read_latest_system_trace(self.get_systrace_alias())

    def read_latest_pstrace(self):
        return self.raw_proxy.read_latest_ps_trace(self.get_pstrace_alias())

    def read_latest_raw_string(self):
        return self.raw_proxy.read_latest_raw_string(self.get_raw_string_alias())
